     1: //! Deterministic IPv4 client-address allocation.
     2: //!
     3: //! A pure function of product state. It performs no I/O, holds no state, and
     4: //! cannot race: the caller supplies the prefix, the reserved server addresses,
     5: //! and every assigned client address, and gets back either a specific address
     6: //! or a bounded error. The same inputs always produce the same answer, which is
     7: //! what makes "the lowest usable free address" a testable claim rather than a
     8: //! hopeful one.
     9: //!
    10: //! The algorithm is a sorted gap scan over `u32` space, never a walk of the
    11: //! address space. A /8 has sixteen million addresses and allocation must be
    12: //! independent of that number.
    13: 
    14: use ipnet::{IpNet, Ipv4Net};
    15: use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
    16: 
    17: /// What allocation was asked for.
    18: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    19: pub enum AddressRequest {
    20:     /// Take the lowest usable address not already reserved.
    21:     Automatic,
    22:     /// Take exactly this address, or explain why it cannot be used.
    23:     Requested(Ipv4Addr),
    24: }
    25: 
    26: /// Everything the allocator needs to know, gathered by the caller inside the
    27: /// mutation transaction.
    28: ///
    29: /// Note that `reserved_clients` deliberately includes *disabled* clients: a
    30: /// disabled client keeps its address, so its address must not be handed to
    31: /// somebody else and then collide when the first client is re-enabled.
    32: #[derive(Clone, Debug)]
    33: pub struct AllocationContext {
    34:     prefix: Ipv4Addr,
    35:     prefix_len: u8,
    36:     /// Server/interface addresses inside the prefix.
    37:     server_addresses: Vec<Ipv4Addr>,
    38:     /// Every managed client's address, enabled or not.
    39:     reserved_clients: Vec<Ipv4Addr>,
    40: }
    41: 
    42: impl AllocationContext {
    43:     /// Builds a context from the selected IPv4 tunnel prefix.
    44:     pub fn new(prefix: IpNet) -> Result<Self, AllocationError> {
    45:         let addr = prefix.addr();
    46:         if !addr.is_ipv4() {
    47:             return Err(AllocationError::NotIpv4);
    48:         }
    49:         let IpNet::V4(v4) = prefix else {
    50:             return Err(AllocationError::NotIpv4);
    51:         };
    52:         let (network, prefix_len) = (v4.network(), v4.prefix_len());
    53:         if prefix_len > 30 {
    54:             // A /31 has no usable host, and /32 is a single address rather than
    55:             // a pool. Treating either as a pool would hand out the network
    56:             // address or produce a range whose bounds cross.
    57:             return Err(AllocationError::PrefixTooSmall(prefix_len));
    58:         }
    59:         Ok(Self {
    60:             prefix: network,
    61:             prefix_len,
    62:             server_addresses: Vec::new(),
    63:             reserved_clients: Vec::new(),
    64:         })
    65:     }
    66: 
    67:     pub fn with_server_addresses(mut self, addresses: impl IntoIterator<Item = Ipv4Addr>) -> Self {
    68:         self.server_addresses.extend(addresses);
    69:         self
    70:     }
    71: 
    72:     pub fn with_reserved_clients(mut self, addresses: impl IntoIterator<Item = Ipv4Addr>) -> Self {
    73:         self.reserved_clients.extend(addresses);
    74:         self
    75:     }
    76: 
    77:     /// The lowest and highest address this prefix may allocate.
    78:     ///
    79:     /// Network and broadcast are excluded wherever the prefix is wide enough to
    80:     /// have them: a /30 is exactly network, two hosts, broadcast.
    81:     ///
    82:     /// Computed in `u64` because a /0 spans all 2^32 addresses, whose last
    83:     /// address is `u32::MAX`. Doing this arithmetic in `u32` wraps a prefix
    84:     /// whose size is a multiple of 2^32 down to an empty one.
    85:     fn usable_bounds(&self) -> Result<(u32, u32), AllocationError> {
    86:         let size = 1u64 << (32 - u32::from(self.prefix_len));
    87:         let base = u64::from(u32::from(self.prefix));
    88:         let last = base
    89:             .checked_add(size - 1)
    90:             .filter(|last| *last <= u64::from(u32::MAX))
    91:             .ok_or(AllocationError::PrefixTooSmall(self.prefix_len))? as u32;
    92: 
    93:         if size <= 2 {
    94:             // /31 or /32: no distinct network/broadcast pair exists to reserve.
    95:             return Ok((u32::from(self.prefix), last));
    96:         }
    97:         Ok((base as u32 + 1, last - 1))
    98:     }
    99: 
   100:     /// Allocates an address according to `request`.
   101:     pub fn allocate(&self, request: AddressRequest) -> Result<Ipv4Addr, AllocationError> {
   102:         let (low, high) = self.usable_bounds()?;
   103:         if low > high {
   104:             return Err(AllocationError::Exhausted);
   105:         }
   106: 
   107:         let used = self.used_set();
   108:         match request {
   109:             AddressRequest::Requested(address) => {
   110:                 let value = u32::from(address);
   111:                 if value < low || value > high {
   112:                     return Err(AllocationError::OutsidePrefix(address));
   113:                 }
   114:                 if used.contains(&value) {
   115:                     return Err(AllocationError::AlreadyUsed(address));
   116:                 }
   117:                 Ok(address)
   118:             }
   119:             AddressRequest::Automatic => {
   120:                 let mut candidate = low;
   121:                 for value in used.range(low..).copied() {
   122:                     if value > high {
   123:                         break;
   124:                     }
   125:                     if value > candidate {
   126:                         // Everything between `candidate` and `value` is free, so
   127:                         // the first gap wins without walking the addresses in it.
   128:                         return Ok(Ipv4Addr::from(candidate));
   129:                     }
   130:                     // `value == candidate`: this address is taken, step over it.
   131:                     candidate = value + 1;
   132:                 }
   133:                 if candidate > high {
   134:                     return Err(AllocationError::Exhausted);
   135:                 }
   136:                 Ok(Ipv4Addr::from(candidate))
   137:             }
   138:         }
   139:     }
   140: 
   141:     /// Every unusable address inside the pool, sorted and deduplicated.
   142:     ///
   143:     /// Built from the product state the caller supplied, so it is exactly the
   144:     /// set the gap scan has to step over. `BTreeSet` gives the sorted iteration
   145:     /// the scan relies on for free, and deduplicates an address that is both a
   146:     /// server address and a client address.
   147:     fn used_set(&self) -> std::collections::BTreeSet<u32> {
   148:         let mut used = std::collections::BTreeSet::new();
   149:         let Ok((low, high)) = self.usable_bounds() else {
   150:             return used;
   151:         };
   152:         // The network address sits below the usable bounds, so it is reserved
   153:         // explicitly rather than being relied upon to fall outside the scan.
   154:         used.insert(u32::from(self.prefix));
   155:         for address in self.server_addresses.iter().chain(&self.reserved_clients) {
   156:             let value = u32::from(*address);
   157:             if (low.saturating_sub(1)..=high.saturating_add(1)).contains(&value) {
   158:                 used.insert(value);
   159:             }
   160:         }
   161:         used
   162:     }
   163: 
   164:     /// The prefix this context allocates inside.
   165:     pub fn prefix(&self) -> IpNet {
   166:         IpNet::V4(Ipv4Net::new(self.prefix, self.prefix_len).expect("a validated prefix"))
   167:     }
   168: }
