   170: /// Deterministic, bounded IPv6 address allocation. It advances over sorted
   171: /// reservations and never walks the address space, so a `/64` costs the same
   172: /// as a small pool. The subnet-router anycast address at the prefix base is
   173: /// reserved; the first candidate is therefore base + 1.
   174: #[derive(Clone, Debug)]
   175: pub struct Ipv6AllocationContext {
   176:     prefix: Ipv6Addr,
   177:     prefix_len: u8,
   178:     server_addresses: Vec<Ipv6Addr>,
   179:     reserved_clients: Vec<Ipv6Addr>,
   180: }
   181: 
   182: impl Ipv6AllocationContext {
   183:     pub fn new(prefix: IpNet) -> Result<Self, AllocationError> {
   184:         let IpNet::V6(prefix) = prefix else {
   185:             return Err(AllocationError::NotIpv6);
   186:         };
   187:         if prefix.prefix_len() > 126
   188:             || prefix.network().is_unspecified()
   189:             || prefix.network().is_multicast()
   190:         {
   191:             return Err(AllocationError::Ipv6PrefixTooSmall(prefix.prefix_len()));
   192:         }
   193:         Ok(Self {
   194:             prefix: prefix.network(),
   195:             prefix_len: prefix.prefix_len(),
   196:             server_addresses: Vec::new(),
   197:             reserved_clients: Vec::new(),
   198:         })
   199:     }
   200: 
   201:     pub fn with_server_addresses(mut self, addresses: impl IntoIterator<Item = Ipv6Addr>) -> Self {
   202:         self.server_addresses.extend(addresses);
   203:         self
   204:     }
   205: 
   206:     pub fn with_reserved_clients(mut self, addresses: impl IntoIterator<Item = Ipv6Addr>) -> Self {
   207:         self.reserved_clients.extend(addresses);
   208:         self
   209:     }
   210: 
   211:     pub fn allocate(&self, request: Option<Ipv6Addr>) -> Result<Ipv6Addr, AllocationError> {
   212:         let network = u128::from(self.prefix);
   213:         let host_bits = 128 - u32::from(self.prefix_len);
   214:         let mask = if host_bits == 128 {
   215:             u128::MAX
   216:         } else {
   217:             (1u128 << host_bits) - 1
   218:         };
   219:         let last = network | mask;
   220:         let used = self
   221:             .server_addresses
   222:             .iter()
   223:             .chain(&self.reserved_clients)
   224:             .map(|address| u128::from(*address))
   225:             .collect::<std::collections::BTreeSet<_>>();
   226: 
   227:         if let Some(address) = request {
   228:             let value = u128::from(address);
   229:             if address.is_unspecified() || address.is_multicast() {
   230:                 return Err(AllocationError::InvalidIpv6Address(address));
   231:             }
   232:             if value <= network || value > last {
   233:                 return Err(AllocationError::Ipv6OutsidePrefix(address));
   234:             }
   235:             if used.contains(&value) {
   236:                 return Err(AllocationError::Ipv6AlreadyUsed(address));
   237:             }
   238:             return Ok(address);
   239:         }
   240: 
   241:         // No broadcast address exists in IPv6. Starting after the reserved
   242:         // subnet-router anycast address, skip only actual occupied addresses.
   243:         let mut candidate = network.checked_add(1).ok_or(AllocationError::Exhausted)?;
   244:         for value in used.range(candidate..=last) {
   245:             if *value > candidate {
   246:                 break;
   247:             }
   248:             if *value == candidate {
   249:                 candidate = candidate.checked_add(1).ok_or(AllocationError::Exhausted)?;
   250:             }
   251:         }
   252:         if candidate > last {
   253:             return Err(AllocationError::Exhausted);
   254:         }
   255:         Ok(Ipv6Addr::from(candidate))
   256:     }
   257: }
