   259: /// Allocates one IPv4 client address inside `prefix`.
   260: ///
   261: /// Convenience over [`AllocationContext::allocate`] for the common case.
   262: pub fn allocate_ipv4(
   263:     prefix: IpNet,
   264:     request: AddressRequest,
   265:     server_addresses: impl IntoIterator<Item = Ipv4Addr>,
   266:     reserved_clients: impl IntoIterator<Item = Ipv4Addr>,
   267: ) -> Result<Ipv4Addr, AllocationError> {
   268:     let context = AllocationContext::new(prefix)?
   269:         .with_server_addresses(server_addresses)
   270:         .with_reserved_clients(reserved_clients);
   271:     context.allocate(request)
   272: }
