   274: /// Narrows any address column to IPv4, which is the only family M001 allocates.
   275: pub fn ipv4_of(address: IpAddr) -> Option<Ipv4Addr> {
   276:     match address {
   277:         IpAddr::V4(v4) => Some(v4),
   278:         IpAddr::V6(_) => None,
   279:     }
   280: }
