   282: #[derive(Clone, Copy, Debug, Eq, PartialEq, thiserror::Error)]
   283: pub enum AllocationError {
   284:     #[error("IPv4 address allocation requires an IPv4 prefix")]
   285:     NotIpv4,
   286:     #[error("IPv6 address allocation requires an IPv6 prefix")]
   287:     NotIpv6,
   288:     #[error("no IPv6 tunnel prefix is configured for this interface")]
   289:     Ipv6NotConfigured,
   290:     #[error("prefix length /{0} is too small to allocate a client address")]
   291:     PrefixTooSmall(u8),
   292:     #[error("every usable address inside the prefix is already assigned")]
   293:     Exhausted,
   294:     #[error("address {0} is outside the selected prefix")]
   295:     OutsidePrefix(Ipv4Addr),
   296:     #[error("address {0} is already assigned or reserved")]
   297:     AlreadyUsed(Ipv4Addr),
   298:     #[error("IPv6 prefix length /{0} must leave server and client host addresses")]
   299:     Ipv6PrefixTooSmall(u8),
   300:     #[error("address {0} is outside the selected IPv6 prefix")]
   301:     Ipv6OutsidePrefix(Ipv6Addr),
   302:     #[error("address {0} is already assigned or reserved")]
   303:     Ipv6AlreadyUsed(Ipv6Addr),
   304:     #[error("address {0} is not a usable IPv6 host address")]
   305:     InvalidIpv6Address(Ipv6Addr),
   306: }
